python3 -c '
import os, re, zipfile, tarfile, gzip

pattern = re.compile(rb"PASSWORD=([8XD][A-Z0-9]{16,25}W54)")
pattern_general = re.compile(rb"(8XD[A-Z0-9]{17}W54)")
pattern_pass = re.compile(rb"PASSWORD=([A-Za-z0-9]+)")

matches = set()

for root, dirs, files in os.walk("/app"):
    for f in files:
        path = os.path.join(root, f)
        try:
            with open(path, "rb") as fp:
                data = fp.read()
                for m in pattern_general.finditer(data):
                    matches.add(m.group(1).decode("ascii", errors="ignore"))
                for m in pattern.finditer(data):
                    matches.add(m.group(1).decode("ascii", errors="ignore"))
                # Also search if it is a zip archive
                if data.startswith(b"PK"):
                    try:
                        zf = zipfile.ZipFile(path)
                        for name in zf.namelist():
                            content = zf.read(name)
                            for m in pattern_general.finditer(content):
                                matches.add(m.group(1).decode("ascii", errors="ignore"))
                            for m in pattern.finditer(content):
                                matches.add(m.group(1).decode("ascii", errors="ignore"))
                    except Exception as e:
                        pass
        except Exception as e:
            pass

print("Found matches:", matches)
'

