    return unless -f $_;
    my $file = $File::Find::name;
    open my $fh, "<:raw", $_ or return;
    local $/;
    my $content = <$fh>;
    close $fh;

    while ($content =~ /(8XD[A-Za-z0-9]{17}W54)/g) {
        $matches{$1} = 1;
    }
    while ($content =~ /PASSWORD=([A-Za-z0-9]+)/g) {
        my $p = $1;
        if ($p =~ /^8XD.*W54$/ && length($p) == 23) {
            $matches{$p} = 1;
        }
    }
}, "/app");

for my $k (keys %matches) {
    print "MATCH: $k\n";
}
