use strict;
use warnings;

my $file = "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat";
open my $fh, "<:raw", $file or die $!;
local $/;
my $content = <$fh>;
close $fh;

# Offset 1048576 is local header
# Let us slice from 1048576 to 3145829 + 22 + comment_length
my $zip_data = substr($content, 1048576, 3145850 - 1048576 + 100);

# Fix central directory header offset in EOCD
# In $zip_data, central dir header PK\x01\x02 was at 3145741.
# Relative to start (1048576), 3145741 - 1048576 = 2097165.
# Let us check EOCD contents.
my $eocd_pos = index($zip_data, "PK\x05\x06");
print "EOCD pos in slice: $eocd_pos\n";
# EOCD structure:
# 0..3: sig (4)
# 4..5: disk num (2)
# 6..7: disk start (2)
# 8..9: records on disk (2)
# 10..11: total records (2)
# 12..15: size of central dir (4)
# 16..19: offset of central dir relative to start of archive (4)
# 20..21: comment len (2)

my $cd_offset_in_slice = index($zip_data, "PK\x01\x02");
print "CD pos in slice: $cd_offset_in_slice\n";

# Rewrite offset in EOCD
substr($zip_data, $eocd_pos + 16, 4, pack("V", $cd_offset_in_slice));

# Also in Central Directory header, check local header offset (bytes 42..45)
# In CD header, local header offset should be 0.
substr($zip_data, $cd_offset_in_slice + 42, 4, pack("V", 0));

open my $out, ">:raw", "/tmp/fixed.zip" or die $!;
print $out $zip_data;
close $out;
' && unzip -l /tmp/fixed.zip && unzip -p /tmp/fixed.zip app/launchcode.txt

