use strict;
use warnings;

my $file = "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat";
open my $fh, "<:raw", $file or die $!;
local $/;
my $content = <$fh>;
close $fh;

my $lh_pos = index($content, "PK\x03\x04");
print "Local Header pos: $lh_pos\n";

# Unpack local header:
# 0..3: sig
# 4..5: version
# 6..7: flags
# 8..9: compression method (0 = stored, 8 = deflated)
# 10..13: time/date
# 14..17: crc32
# 18..21: compressed size
# 22..25: uncompressed size
# 26..27: filename length
# 28..29: extra field length

my ($ver, $flags, $method, $time, $date, $crc, $csize, $usize, $fnlen, $extralen) =
    unpack("v v v v v V V V v v", substr($content, $lh_pos + 4, 26));

print "Method: $method\n";
print "CRC32: ", sprintf("%x", $crc), "\n";
print "Comp size: $csize\n";
print "Uncomp size: $usize\n";
print "Filename len: $fnlen\n";
print "Extra len: $extralen\n";

my $filename = substr($content, $lh_pos + 30, $fnlen);
print "Filename: $filename\n";

my $data_offset = $lh_pos + 30 + $fnlen + $extralen;
my $data = substr($content, $data_offset, $csize);

print "Raw data (33 bytes):\n";
for (my $i=0; $i<length($data); $i++) {
    printf("%02x ", ord(substr($data, $i, 1)));
}
print "\n";
print "Raw ASCII: $data\n";
'

